async function sendMessage(msg: Message) {
  const fname = filename(msg);
  // stage locally first so nothing is ever lost
  await fs.writeFile(path.join(LOCAL_QUEUE, fname), render(msg));
  try {
    await fs.writeFile(path.join(SMB_MOUNT_INBOX, fname), render(msg));
  } catch (e) {
    log.warn(`mount write failed, message queued: ${e.message}`);
  }
  return { sent: true, id: msg.id };
}
